   8: 
   9: export const CLI_PATH = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'jsonpatch-cli.mjs');
  10: export const USAGE = 'Usage: node jsonpatch-cli.mjs <patch> [<doc>]';
  11: export const MAX = 1048576;
  12: export const BOM = Buffer.from([0xef, 0xbb, 0xbf]);
  13: 
  14: export function run(args, { input, cwd, stdio } = {}) {
  15:   // No `encoding` option: spawnSync returns Buffers, and string input is encoded as UTF-8 here.
  16:   const bytes = typeof input === 'string' ? Buffer.from(input, 'utf8') : input;
  17:   const opts = { input: bytes, cwd, maxBuffer: 64 * 1024 * 1024 };
  18:   if (stdio) {
  19:     delete opts.input;
  20:     opts.stdio = stdio;
  21:   }
  22:   const r = spawnSync(process.execPath, [CLI_PATH, ...args], opts);
  23:   return {
  24:     code: r.status,
  25:     stdout: r.stdout ? r.stdout.toString('utf8') : '',
  26:     stderr: r.stderr ? r.stderr.toString('utf8') : '',
  27:   };
  28: }
  29: 
  30: export function expectError(res, line, code) {
  31:   assert.equal(res.code, code);
  32:   assert.equal(res.stdout, '');
  33:   assert.equal(res.stderr, line + '\n');
  34: }
  35: 
  36: export function expectOk(res, value) {
  37:   assert.equal(res.code, 0);
  38:   assert.equal(res.stderr, '');
  39:   assert.equal(res.stdout, JSON.stringify(value, null, 2) + '\n');
  40: }
