helpers.mjs
   1: import assert from 'node:assert/strict';
   2: import { applyPatch, PatchError } from '../jsonpatch.mjs';
   3: 
   4: export function expectPatchError(doc, patch, message, index) {
   5:   let thrown;
   6:   try {
   7:     applyPatch(doc, patch);
   8:   } catch (err) {
   9:     thrown = err;
  10:   }
  11:   assert.notStrictEqual(thrown, undefined, 'expected applyPatch to throw');
  12:   assert.ok(thrown instanceof PatchError, 'instanceof PatchError');
  13:   assert.ok(thrown instanceof Error, 'instanceof Error');
  14:   assert.strictEqual(thrown.name, 'PatchError');
  15:   assert.strictEqual(thrown.message, message);
  16:   assert.strictEqual(thrown.index, index);
  17: }
  18: 
  19: export function expectOpError(doc, op, reason) {
  20:   expectPatchError(doc, [op], `operation 0: ${reason}`, 0);
  21: }
  22: 
  23: export function deepClone(v) {
  24:   if (Array.isArray(v)) return v.map(deepClone);
  25:   if (v !== null && typeof v === 'object') {
  26:     const out = {};
  27:     for (const k of Object.keys(v)) {
  28:       Object.defineProperty(out, k, {
  29:         value: deepClone(v[k]),
  30:         writable: true,
  31:         enumerable: true,
  32:         configurable: true,
  33:       });
  34:     }
  35:     return out;
  36:   }
  37:   return v;
  38: }
  39: 
  40: export function collectObjects(v, set = new Set()) {
  41:   if (v !== null && typeof v === 'object' && !set.has(v)) {
  42:     set.add(v);
  43:     for (const k of Object.keys(v)) collectObjects(v[k], set);
  44:   }
  45:   return set;
  46: }
patch-copies.test.mjs
   1: import { test } from 'node:test';
   2: import assert from 'node:assert/strict';
   3: import { applyPatch } from '../jsonpatch.mjs';
   4: import { deepClone, collectObjects, expectPatchError } from './helpers.mjs';
   5: 
   6: // --- immutability ---
   7: 
   8: function assertUntouched(doc, patch, message, index) {
   9:   const docSnap = deepClone(doc);
  10:   const patchSnap = deepClone(patch);
  11:   if (message === null) {
  12:     assert.doesNotThrow(() => applyPatch(doc, patch));
  13:   } else {
  14:     expectPatchError(doc, patch, message, index);
  15:   }
  16:   assert.deepStrictEqual(doc, docSnap);
  17:   assert.deepStrictEqual(patch, patchSnap);
  18: }
  19: 
  20: test('doc and patch unchanged after a successful patch', () => {
  21:   const doc = { a: [1, { b: -0 }], c: { d: 1 } };
  22:   const patch = [
  23:     { op: 'add', path: '/a/-', value: { x: [-0] } },
  24:     { op: 'replace', path: '/c/d', value: [1, 2] },
  25:     { op: 'move', from: '/a/0', path: '/e' },
  26:     { op: 'copy', from: '/c', path: '/f' },
  27:     { op: 'remove', path: '/a/0' },
  28:     { op: 'test', path: '/e', value: 1 },
  29:   ];
  30:   assertUntouched(doc, patch, null);
  31: });
  32: 
  33: test('doc and patch unchanged when a later op fails (add then test fails)', () => {
  34:   const doc = { a: [1, 2], b: { c: 1 } };
  35:   const patch = [
  36:     { op: 'add', path: '/a/0', value: { z: 1 } },
  37:     { op: 'test', path: '/b/c', value: 2 },
  38:   ];
  39:   assertUntouched(doc, patch, 'operation 1: test failed', 1);
  40: });
  41: 
  42: test('doc and patch unchanged when a later op fails (remove then move fails)', () => {
  43:   const doc = { a: [1, 2], b: { c: 1 } };
