  45:     { op: 'remove', path: '/a/0' },
  46:     { op: 'move', from: '/nope', path: '/q' },
  47:   ];
  48:   assertUntouched(doc, patch, 'operation 1: from not found', 1);
  49: });
  50: 
  51: test('doc and patch unchanged on form error', () => {
  52:   const doc = { a: 1 };
  53:   const patch = [{ op: 'remove', path: '/a' }, { op: 'bogus' }];
  54:   assertUntouched(doc, patch, 'operation 1: bad op', 1);
  55: });
  56: 
  57: // --- no shared objects ---
  58: 
  59: function assertDisjoint(doc, patch) {
  60:   const result = applyPatch(doc, patch);
  61:   const inputs = collectObjects(patch, collectObjects(doc));
  62:   for (const obj of collectObjects(result)) {
  63:     assert.strictEqual(inputs.has(obj), false, 'result shares an object with the inputs');
  64:   }
  65:   return result;
  66: }
  67: 
  68: const nested = () => ({ a: { b: [1, { c: 2 }] }, d: [[1], [2]] });
  69: 
  70: test('disjoint: patch [] on nested doc', () => {
  71:   const doc = nested();
  72:   const r = assertDisjoint(doc, []);
  73:   assert.deepStrictEqual(r, nested());
  74:   assert.notStrictEqual(r, doc);
  75: });
  76: 
  77: test('disjoint: add with object value', () => {
  78:   const op = { op: 'add', path: '/n', value: { x: [1] } };
  79:   const r = assertDisjoint(nested(), [op]);
  80:   assert.notStrictEqual(r.n, op.value);
  81:   assert.notStrictEqual(r.n.x, op.value.x);
  82: });
  83: 
  84: test('disjoint: replace with array value', () => {
  85:   const op = { op: 'replace', path: '/a', value: [{ y: 1 }] };
  86:   const r = assertDisjoint(nested(), [op]);
  87:   assert.notStrictEqual(r.a, op.value);
  88:   assert.notStrictEqual(r.a[0], op.value[0]);
  89: });
  90: 
  91: test('disjoint: copy', () => {
  92:   assertDisjoint(nested(), [{ op: 'copy', from: '/a', path: '/z' }]);
  93: });
  94: 
  95: test('disjoint: move', () => {
  96:   assertDisjoint(nested(), [{ op: 'move', from: '/a', path: '/z' }]);
  97: });
  98: 
  99: test('disjoint: test with object value', () => {
 100:   assertDisjoint(nested(), [{ op: 'test', path: '/a', value: { b: [1, { c: 2 }] } }]);
 101: });
 102: 
 103: test('disjoint: add "" with object value', () => {
 104:   const op = { op: 'add', path: '', value: { k: [1] } };
