patch-ops.test.mjs
   1: import { test } from 'node:test';
   2: import assert from 'node:assert/strict';
   3: import { applyPatch } from '../jsonpatch.mjs';
   4: import { expectOpError, expectPatchError } from './helpers.mjs';
   5: 
   6: const add = (path, value) => ({ op: 'add', path, value });
   7: const remove = (path) => ({ op: 'remove', path });
   8: const replace = (path, value) => ({ op: 'replace', path, value });
   9: const move = (from, path) => ({ op: 'move', from, path });
  10: const copy = (from, path) => ({ op: 'copy', from, path });
  11: const testOp = (path, value) => ({ op: 'test', path, value });
  12: const apply = (doc, ...ops) => applyPatch(doc, ops);
  13: 
  14: // --- add ---
  15: 
  16: test('add at root replaces the document', () => {
  17:   assert.deepStrictEqual(apply({ a: 1 }, add('', [1])), [1]);
  18:   assert.strictEqual(apply({ a: 1 }, add('', 5)), 5);
  19:   assert.strictEqual(apply({ a: 1 }, add('', null)), null);
  20: });
  21: 
  22: test('add new object member', () => {
  23:   assert.deepStrictEqual(apply({ a: 1 }, add('/b', 2)), { a: 1, b: 2 });
  24: });
  25: 
  26: test('add existing member keeps its place', () => {
  27:   const r = apply({ a: 1, b: 2 }, add('/a', 9));
  28:   assert.deepStrictEqual(Object.keys(r), ['a', 'b']);
  29:   assert.strictEqual(JSON.stringify(r), '{"a":9,"b":2}');
  30: });
  31: 
  32: test('add "/__proto__" is an ordinary own member', () => {
  33:   const r = apply({}, add('/__proto__', { x: 1 }));
  34:   assert.strictEqual(Object.hasOwn(r, '__proto__'), true);
  35:   assert.strictEqual(Object.getPrototypeOf(r), Object.prototype);
  36:   assert.deepStrictEqual(Object.keys(r), ['__proto__']);
  37:   assert.deepStrictEqual(r.__proto__, { x: 1 });
  38:   assert.strictEqual(Object.getPrototypeOf(r) === Object.prototype, true);
  39:   assert.strictEqual(({}).x, undefined);
  40: });
  41: 
  42: test('add array append with "-"', () => {
  43:   assert.deepStrictEqual(apply([1, 2], add('/-', 3)), [1, 2, 3]);
  44: });
  45: 
  46: test('add array at index shifts up', () => {
  47:   assert.deepStrictEqual(apply([1, 2], add('/2', 'x')), [1, 2, 'x']);
  48:   assert.deepStrictEqual(apply([1, 2], add('/1', 'x')), [1, 'x', 2]);
  49:   assert.deepStrictEqual(apply([1, 2], add('/0', 'x')), ['x', 1, 2]);
  50:   assert.deepStrictEqual(apply([], add('/0', 'x')), ['x']);
  51: });
  52: 
  53: test('add array index beyond length fails', () => {
  54:   expectOpError([1, 2], add('/3', 'x'), 'path not found');
  55: });
  56: 
  57: test('add array bad index', () => {
  58:   const doc = { arr: [1, 2] };
  59:   for (const tok of ['01', '1.0', '', '+1', '1e0', ' 1', 'length', '-1', 'a']) {
  60:     expectOpError(doc, add(`/arr/${tok}`, 0), 'bad index');
  61:   }
  62: });
  63: 
  64: test('add into nested array and object', () => {
  65:   assert.deepStrictEqual(apply({ a: [{ b: [1] }] }, add('/a/0/b/-', 2)), { a: [{ b: [1, 2] }] });
  66: });
  67: 
  68: test('add last token fails when parent is not object or array', () => {
  69:   expectOpError({ a: 1 }, add('/a/b', 0), 'path not found');
  70:   expectOpError({ a: 'str' }, add('/a/0', 0), 'path not found');
  71:   expectOpError({ a: null }, add('/a/b', 0), 'path not found');
  72:   expectOpError({ a: true }, add('/a/b', 0), 'path not found');
  73: });
  74: 
  75: test('add parent missing fails', () => {
  76:   expectOpError({}, add('/a/b', 0), 'path not found');
  77: });
  78: 
  79: test('add through "-" parent fails with path not found', () => {
  80:   expectOpError({ arr: [1] }, add('/arr/-/x', 0), 'path not found');
  81: });
  82: 
  83: test('add "/a" on non-container root fails', () => {
  84:   expectOpError(5, add('/a', 0), 'path not found');
  85:   expectOpError(null, add('/a', 0), 'path not found');
  86: });
  87: 
  88: test('add at "/" uses the empty-name member', () => {
  89:   assert.deepStrictEqual(apply({}, add('/', 1)), { '': 1 });
  90: });
  91: 
  92: // --- remove ---
  93: 
  94: test('remove object member', () => {
  95:   assert.deepStrictEqual(apply({ a: 1, b: 2 }, remove('/a')), { b: 2 });
  96: });
  97: 
  98: test('remove array element shifts later down', () => {
  99:   assert.deepStrictEqual(apply([1, 2, 3], remove('/0')), [2, 3]);
 100:   assert.deepStrictEqual(apply([1, 2, 3], remove('/2')), [1, 2]);
 101: });
 102: 
 103: test('remove nested', () => {
 104:   assert.deepStrictEqual(apply({ a: { b: [1, 2] } }, remove('/a/b/0')), { a: { b: [2] } });
 105: });
 106: 
 107: test('remove missing fails', () => {
 108:   expectOpError({}, remove('/a'), 'path not found');
 109:   expectOpError([1, 2], remove('/2'), 'path not found');
 110:   expectOpError({ a: 1 }, remove('/a/b'), 'path not found');
 111: });
 112: 
 113: test('remove "-" fails with path not found', () => {
 114:   expectOpError({ arr: [1, 2] }, remove('/arr/-'), 'path not found');
 115: });
 116: 
 117: test('remove on inherited names fails', () => {
 118:   for (const name of ['toString', 'constructor', '__proto__', 'hasOwnProperty']) {
 119:     expectOpError({}, remove(`/${name}`), 'path not found');
 120:   }
 121: });
 122: 
 123: test('remove "/constructor/name" fails', () => {
 124:   expectOpError({}, remove('/constructor/name'), 'path not found');
 125: });
 126: 
 127: test('remove own "__proto__" member from parsed JSON', () => {
 128:   const doc = JSON.parse('{"__proto__": 1, "a": 2}');
 129:   const r = apply(doc, remove('/__proto__'));
 130:   assert.deepStrictEqual(Object.keys(r), ['a']);
 131: });
 132: 
 133: // --- replace ---
 134: 
 135: test('replace root', () => {
 136:   assert.deepStrictEqual(apply({ a: 1 }, replace('', [2])), [2]);
 137:   assert.strictEqual(apply({ a: 1 }, replace('', 0)), 0);
 138: });
 139: 
 140: test('replace member keeps its place', () => {
 141:   const r = apply({ a: 1, b: 2 }, replace('/a', 9));
 142:   assert.deepStrictEqual(Object.keys(r), ['a', 'b']);
 143:   assert.strictEqual(JSON.stringify(r), '{"a":9,"b":2}');
 144: });
 145: 
 146: test('replace array element', () => {
 147:   assert.deepStrictEqual(apply([1, 2], replace('/1', 'x')), [1, 'x']);
 148: });
 149: 
 150: test('replace missing fails', () => {
 151:   expectOpError([1, 2], replace('/2', 0), 'path not found');
 152:   expectOpError([1, 2], replace('/-', 0), 'path not found');
 153:   expectOpError({}, replace('/a', 0), 'path not found');
 154: });
 155: 
 156: test('replace bad index', () => {
 157:   expectOpError({ arr: [1, 2] }, replace('/arr/01', 0), 'bad index');
 158: });
 159: 
 160: test('replace inherited names fail', () => {
 161:   for (const name of ['toString', 'constructor', '__proto__', 'hasOwnProperty']) {
 162:     expectOpError({}, replace(`/${name}`, 1), 'path not found');
 163:   }
 164:   expectOpError({}, replace('/constructor/name', 1), 'path not found');
 165: });
 166: 
 167: test('replace "/arr/-" fails with path not found', () => {
 168:   expectOpError({ arr: [1] }, replace('/arr/-', 1), 'path not found');
 169: });
 170: 
 171: // --- move ---
 172: 
 173: test('move between object members', () => {
 174:   assert.deepStrictEqual(apply({ a: 1 }, move('/a', '/b')), { b: 1 });
 175: });
 176: 
 177: test('move from /a to /b keeps b last', () => {
 178:   const r = apply({ a: 1, c: 3, b: 2 }, move('/a', '/b'));
 179:   assert.deepStrictEqual(Object.keys(r), ['c', 'b']);
 180:   assert.strictEqual(JSON.stringify(r), '{"c":3,"b":1}');
 181: });
 182: 
 183: test('move in array counts index after removal', () => {
 184:   assert.deepStrictEqual(apply([1, 2, 3], move('/0', '/2')), [2, 3, 1]);
 185:   assert.deepStrictEqual(apply([1, 2, 3], move('/2', '/0')), [3, 1, 2]);
 186: });
 187: 
 188: test('move to index beyond length after removal fails', () => {
 189:   expectOpError([1, 2, 3], move('/0', '/3'), 'path not found');
 190: });
 191: 
 192: test('move to array end with "-"', () => {
 193:   assert.deepStrictEqual(apply([1, 2, 3], move('/0', '/-')), [2, 3, 1]);
 194: });
 195: 
 196: test('move with from === path leaves doc unchanged', () => {
 197:   assert.deepStrictEqual(apply({ a: 1 }, move('/a', '/a')), { a: 1 });
 198:   assert.deepStrictEqual(apply([1, 2], move('/0', '/0')), [1, 2]);
 199: });
 200: 
 201: test('move with from === path still requires from', () => {
 202:   expectOpError({}, move('/x', '/x'), 'from not found');
 203: });
 204: 
 205: test('move from missing fails with from not found', () => {
 206:   expectOpError({}, move('/a', '/b'), 'from not found');
 207:   expectOpError({}, move('/a', '/x/y'), 'from not found');
 208: });
 209: 
 210: test('move into missing parent fails with path not found', () => {
 211:   expectOpError({ a: 1 }, move('/a', '/x/y'), 'path not found');
 212: });
 213: 
 214: test('move bad index in from', () => {
 215:   expectOpError({ arr: [1] }, move('/arr/01', '/b'), 'bad index');
 216: });
 217: 
 218: test('move deep value to ancestor replaces it', () => {
 219:   assert.deepStrictEqual(apply({ a: { b: { c: 1 } } }, move('/a/b', '/a')), { a: { c: 1 } });
 220: });
 221: 
 222: // --- copy ---
 223: 
 224: test('copy to another member', () => {
 225:   assert.deepStrictEqual(apply({ a: { x: 1 } }, copy('/a', '/b')), { a: { x: 1 }, b: { x: 1 } });
 226: });
 227: 
 228: test('copy into array', () => {
 229:   assert.deepStrictEqual(apply([1, 2], copy('/0', '/-')), [1, 2, 1]);
 230:   assert.deepStrictEqual(apply([1, 2], copy('/1', '/0')), [2, 1, 2]);
 231: });
 232: 
 233: test('copy path may lie inside from', () => {
 234:   assert.deepStrictEqual(
 235:     apply({ a: { x: 1 } }, copy('/a', '/a/b')),
